    try {
      // 根据是否存在 'query' 字段确定使用哪种方法
      if (pagination && pagination.query) {
        return await this.catalogService.searchSongs(pagination.query, pagination);
      } else {
        return await this.catalogService.listSongs(pagination);
      }
    } catch (error) {
      console.error('获取歌曲时出错:', error);
      throw error;
    }
  }
}
